"use client";

import { useRouter } from "next/navigation";
import { useState, useEffect } from "react";
import { Dumbbell, ShieldAlert, CheckCircle2 } from "lucide-react";
import { supabase } from "@/lib/supabaseClient";

export default function Onboarding() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  // Quick auth check so guests can't see this page
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!session) {
        router.push("/login");
      }
    });
  }, [router]);

  const completeOnboarding = () => {
    setLoading(true);
    router.push("/");
  };

  return (
    <div className="min-h-screen bg-background flex flex-col items-center justify-center p-6 py-12">
      <div className="max-w-2xl w-full flex flex-col sm:flex-row gap-8 items-stretch">
        
        {/* Rules Panel */}
        <div className="flex-1 bg-dark-panel p-8 rounded-3xl border border-border shadow-2xl animate-in flip-in-y duration-700">
          <div className="mb-8">
            <h1 className="text-3xl font-black uppercase tracking-widest text-primary flex items-center gap-3">
              <ShieldAlert className="w-8 h-8" />
              The Rules
            </h1>
            <p className="text-gray-400 font-medium mt-2 leading-relaxed">
              75 Hard is not a fitness challenge. It is a transformative mental toughness program. If you fail to complete any daily task, your progress drops to zero and you start from Day 1. There are no excuses.
            </p>
          </div>

          <div className="space-y-4">
            {[
              "Follow a strict diet with absolutely no alcohol and NO cheat meals.",
              "Complete two 45-minute daily workouts. One MUST be outdoors.",
              "Drink 1 US Gallon (3.8 liters) of water.",
              "Read 10 pages of a non-fiction entrepreneurship or personal development book.",
              "Take a daily progress photo.",
              "Mandatory non-negotiable sleep (At least 6 hours, configured by this tracker)."
            ].map((rule, idx) => (
              <div key={idx} className="flex items-start gap-4 p-4 bg-background border border-border rounded-xl">
                <div className="w-8 h-8 rounded-full bg-dark-panel border border-border flex items-center justify-center font-bold text-primary shrink-0">
                  {idx + 1}
                </div>
                <p className="text-sm text-gray-300 font-medium leading-relaxed">{rule}</p>
              </div>
            ))}
          </div>

          <div className="mt-8 pt-8 border-t border-border">
            <button
              onClick={completeOnboarding}
              disabled={loading}
              className="w-full py-5 rounded-2xl bg-primary text-white font-black uppercase tracking-widest hover:bg-primary-hover shadow-lg hover:-translate-y-1 transition-all duration-300 flex items-center justify-center gap-2"
            >
              {loading ? <Dumbbell className="w-6 h-6 animate-spin" /> : "I Accept The Challenge"}
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}
